// Normalize incoming WhatsApp payload to standard lead format
const msg = $input.first().json;
const lead = {
  phone: msg.data?.from || msg.from || '',
  message: msg.data?.body || msg.body || msg.text || '',
  name: msg.data?.fromName || msg.data?.name || '',
  timestamp: new Date().toISOString(),
  source: 'whatsapp'};

// Simple keyword-based urgency detection (no paid API required)
const urgentKeywords = ['preço', 'price', 'comprar', 'buy', 'contratar', 'urgente', 'orçamento', 'demissão', 'demissao', 'folha', 'payroll', 'admissão', 'admissao', 'férias'];
const msgLower = (lead.message || '').toLowerCase();
lead.intent_score = urgentKeywords.some(k => msgLower.includes(k)) ? 9 : 5;
lead.urgency = lead.intent_score >= 8 ? 'HOT' : 'WARM';

return [{ json: lead }];

// Route hot leads to CRM / Google Sheets
const lead = $input.first().json;
if (lead.urgency === 'HOT') {
  return [{ json: lead }];
}
return [];

